selected.compute:
options = read('/input/options')
ids = [x['id'] for x in options]
result = []
for k in range(2, 5):
    if result == []:
        for choice in combinations(ids, k):
            candidate = list(choice)
            if valid(candidate):
                result = candidate
                break

selected.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
    else:
        result = []
if result != []:
    if not exists('/output/selection'):
        write('/output/selection', result)
    delivery = receipt('report')
    if delivery == 'unknown':
        delivery_status = status('report')
        if delivery_status == 'not_sent':
            send('report', 'team', result)
    elif delivery == 'unattempted' or delivery == 'failure':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
